from datetime import date, datetime, time, timedelta
from decimal import Decimal, InvalidOperation
import json
import sqlite3

from dateutil import parser
import pandas as pd
import requests

import calendar_import
import categories
import config
import database
import models


class ImportRejected(ValueError):
    """Represent a sanity rejection that must preserve existing data and snapshots."""


def read_private_sources(path=config.PRIVATE_SOURCES_FILE):
    """Read optional private source settings without displaying or logging their contents."""
    if not path.exists():
        return {}
    settings = json.loads(path.read_text(encoding='utf-8'))
    if not isinstance(settings, dict):
        raise ValueError('Source configuration must be an object.')
    return settings


def fetch_json(url, token):
    """Fetch a verified HTTPS source with a bounded timeout and optional Bearer token."""
    if not isinstance(url, str) or not url.startswith('https://'):
        raise ValueError('Source URL must use HTTPS.')
    headers = {'Authorization': f'Bearer {token}'} if token else {}
    # Course: A06 – all calls use timeouts and failures are handled by the source pipeline.
    response = requests.get(url, headers=headers, timeout=config.HTTP_TIMEOUT_SECONDS)
    response.raise_for_status()
    return response.json()


def _text(value):
    """Normalize optional source text and blank spreadsheet cells."""
    if value is None or pd.isna(value):
        return ''
    return str(value).strip()


def _date(value):
    """Parse a source date or spreadsheet timestamp."""
    if isinstance(value, datetime):
        return value.date()
    return value if isinstance(value, date) else parser.parse(str(value)).date()


def _time(value):
    """Parse a spreadsheet time without consulting the host timezone."""
    if isinstance(value, time):
        return value
    if isinstance(value, datetime):
        return value.time()
    return datetime.strptime(_text(value), config.SOURCE_TIME_FORMAT).time()


def _timestamp(value, field):
    """Convert source timestamps at the calendar boundary and sanitize parser errors."""
    try:
        value = value if isinstance(value, datetime) else parser.parse(value)
        return calendar_import.to_local_naive(value)
    except (ValueError, TypeError, OverflowError) as error:
        raise ValueError(f'Invalid {field}.') from error


def expand_weekly_course(weekday, start_time, end_time, valid_from, valid_to):
    """Return weekly (start,end) pairs inside an inclusive validity range."""
    if isinstance(weekday, str):
        weekday = config.WEEKDAY_NAMES.get(weekday.strip().lower().rstrip('.'))
    if type(weekday) is not int or not 0 <= weekday < config.DAYS_PER_WEEK:
        raise ValueError('Invalid weekday.')
    if valid_to < valid_from:
        raise ValueError('valid_to must not precede valid_from.')
    day = valid_from + timedelta(days=(weekday - valid_from.weekday()) % config.DAYS_PER_WEEK)
    result = []
    while day <= valid_to:
        if len(result) >= config.MAX_RECORDS_PER_SOURCE:
            raise ImportRejected('Too many weekly occurrences.')
        start = datetime.combine(day, start_time)
        end = None if end_time is None else datetime.combine(day, end_time)
        if end is not None and end <= start:
            end += timedelta(days=1)
        result.append((start, end))
        day += timedelta(days=config.DAYS_PER_WEEK)
    return result


def _excel_intervals(row, now):
    """Expand a one-off or weekly source row using configured defaults."""
    start, end = _time(row.get('start_time')), None
    if _text(row.get('end_time')):
        end = _time(row['end_time'])
    if _text(row.get('date')):
        day = _date(row['date'])
        return expand_weekly_course(day.weekday(), start, end, day, day)
    anchor = now.date() - timedelta(days=now.weekday())
    first = anchor - timedelta(weeks=config.HISTORY_WEEKS)
    last = config.UNISPORT_DEFAULT_VALID_TO
    if _text(row.get('valid_from')):
        first = _date(row['valid_from'])
    if _text(row.get('valid_to')):
        last = _date(row['valid_to'])
    return expand_weekly_course(_text(row.get('weekday')), start, end, first, last)


def load_unisport_excel(path, column_mapping, now=None):
    """Read actual Excel input with configurable headers and sanitized row-level errors."""
    # Course: A08 – pandas loads and renames tabular source columns.
    frame = pd.read_excel(path).rename(columns=column_mapping)
    if len(frame) > config.MAX_RECORDS_PER_SOURCE:
        raise ImportRejected('Too many source rows.')
    result = []
    for row in frame.to_dict('records'):
        try:
            for start, end in _excel_intervals(row, config.local_now(now)):
                record = {}
                for field in config.OPTIONAL_RECORD_TEXT_FIELDS:
                    record[field] = _text(row.get(field))
                record.update(source='unisport', title=_text(row.get('title')),
                              external_id=_text(row.get('course_id')), start=start, end=end,
                              organizer='Unisport HSG', price=_text(row.get('price_chf')),
                              status='open', is_recurring=not bool(_text(row.get('date'))))
                result.append(normalize_record(record))
            if len(result) > config.MAX_RECORDS_PER_SOURCE:
                raise ImportRejected('Too many expanded occurrences.')
        except ImportRejected:
            raise
        except (ValueError, TypeError, OverflowError):
            result.append({'_error': 'Invalid title, date, weekday, course time or price.'})
    return result


def _parse_payload(payload, field_mapping, source):
    """Normalize list/envelope payloads, keeping bad rows isolated from valid ones."""
    rows = payload.get('events') if isinstance(payload, dict) else payload
    if not isinstance(rows, list):
        raise ValueError('Source payload must contain an events list.')
    if len(rows) > config.MAX_RECORDS_PER_SOURCE:
        raise ImportRejected('Too many source records.')
    result = []
    for row in rows:
        try:
            result.append(_payload_record(row, field_mapping, source))
        except ValueError as error:
            result.append({'_error': str(error)})
        except (TypeError, OverflowError):
            result.append({'_error': 'Invalid event fields.'})
    return result


def _payload_record(row, mapping, source):
    """Map one raw JSON event, discarding untrusted internal error markers."""
    if not isinstance(row, dict):
        raise ValueError('Event must be an object.')
    record = {}
    for key, value in row.items():
        if not key.startswith('_'):
            record[mapping.get(key, key)] = value
    club = record.pop('club', None)
    if isinstance(club, dict):
        record['club_name'] = club.get('name', '')
        record['club_category'] = club.get('category', '')
    record['source'] = source
    record['organizer'] = record.get('organizer') or record.get('club_name', '')
    # Convert numeric JSON prices via their decimal spelling, before internal money validation.
    if isinstance(record.get('price'), (int, float)):
        record['price'] = str(record['price'])
    return normalize_record(record)


def parse_uniclubs_payload(payload, field_mapping):
    """Return canonical UniClubs records."""
    return _parse_payload(payload, field_mapping, 'uniclubs')


def parse_city_payload(payload, field_mapping):
    """Return canonical city records."""
    return _parse_payload(payload, field_mapping, 'city')


def classify_location(location_text):
    """Apply online, TBA, elsewhere and local precedence (SPEC section 7.5)."""
    text = _text(location_text).lower()
    for kind in ('online', 'tba', 'elsewhere'):
        if kind == 'tba' and not text:
            return kind
        if any(word in text for word in config.LOCATION_KEYWORDS[kind]):
            return kind
    return 'st_gallen'


def estimate_end(start, event_type):
    """Estimate a missing end, normally ninety minutes after the start."""
    minutes = config.DEFAULT_DURATION_MINUTES
    if config.USE_TYPE_DURATIONS:
        minutes = config.DURATION_BY_TYPE_MINUTES.get(event_type, minutes)
    return start + timedelta(minutes=minutes)


def _parse_price(value):
    """Parse decimal price text while preserving unknown and free prices distinctly."""
    if value is None or value == '':
        return None
    if isinstance(value, Decimal):
        models.price_to_rappen(value)
        return value
    if not isinstance(value, str):
        raise ValueError('Invalid price: expected decimal text.')
    text = value.strip().lower().replace('chf', '').strip()
    if text in config.FREE_PRICE_WORDS:
        return Decimal('0')
    try:
        result = Decimal(text)
        models.price_to_rappen(result)
        return result
    except (InvalidOperation, ValueError) as error:
        raise ValueError('Invalid price.') from error


def _boolean(value, field):
    """Accept booleans and explicit textual spellings instead of bool('false')."""
    if value is None or value == '':
        return False
    if isinstance(value, bool):
        return value
    if type(value) is int and value in (0, 1):
        return bool(value)
    if isinstance(value, str) and value.strip().lower() in config.BOOLEAN_TEXT:
        return config.BOOLEAN_TEXT[value.strip().lower()]
    raise ValueError(f'Invalid {field}.')


def normalize_record(raw):
    """Validate canonical fields before any database mutation and return a normalized copy."""
    if not isinstance(raw, dict):
        raise ValueError('Record must be an object.')
    if '_error' in raw:
        raise ValueError(raw['_error'])
    row = raw.copy()
    if row.get('source') not in config.SOURCES:
        raise ValueError('Invalid source.')
    row['title'] = _text(row.get('title'))
    if not row['title']:
        raise ValueError('Missing title.')
    for field in config.OPTIONAL_RECORD_TEXT_FIELDS:
        row[field] = _text(row.get(field))
    row['start'] = _timestamp(row.get('start'), 'start')
    missing_end = row.get('end') is None or row.get('end') == ''
    row['end_is_estimated'] = missing_end or row.get('end_is_estimated', False)
    row['end'] = estimate_end(row['start'], row['event_type']) if missing_end else _timestamp(
        row['end'], 'end')
    if row['end'] <= row['start']:
        raise ValueError('Invalid end: must be after start.')
    row['price'] = _parse_price(row.get('price'))
    row['location_type'] = classify_location(row['location'])
    row['status'] = _text(row.get('status', 'open')).lower().replace(' ', '_')
    if row['status'] not in config.EVENT_STATUSES:
        raise ValueError('Invalid status.')
    for field in ('members_only', 'is_recurring'):
        row[field] = _boolean(row.get(field), field)
    row['members_only'] = row['members_only'] or row['status'] == 'members_only'
    title, start, location = row['title'], row['start'], row['location']
    row['external_id'] = _text(row.get('external_id')) or (
        f'{title}|{start.weekday()}|{start:%H:%M}|{location}')
    return row


def save_records(connection, records, source, taxonomy, include_past=False, now=None,
                 is_placeholder=False, reconcile=False):
    """Validate a bounded batch, then atomically save its valid records and return diagnostics."""
    if source not in config.SOURCES or len(records) > config.MAX_RECORDS_PER_SOURCE:
        raise ImportRejected('Invalid source or too many source records.')
    prepared, skipped, past = [], [], 0
    for position, raw in enumerate(records, 1):
        try:
            row = normalize_record(raw)
            if row['source'] != source:
                raise ValueError('Source does not match the batch.')
            if not include_past and row['end'] < config.local_now(now):
                past += 1
                continue
            _, row['bundle_key'] = categories.assign_category(row, taxonomy)
            row['is_placeholder'] = is_placeholder
            prepared.append(row)
        except ValueError as error:
            skipped.append(f'Row {position}: {error}')
    if not prepared and skipped:
        raise ImportRejected('No valid source records; existing data retained.')
    counts = database.apply_source_records(connection, prepared, source,
                                           reconcile=reconcile and not skipped, now=now)
    return {'source': source, 'n_series': counts[0], 'n_events': counts[1],
            'rows_read': len(records), 'skipped': skipped, 'past': past}


def _load_candidate(source, origin, path, settings, now):
    """Read one candidate and preserve the raw JSON only for a validated live snapshot."""
    if source == 'unisport':
        return load_unisport_excel(path, config.UNISPORT_COLUMN_MAPPING, now), None
    payload = fetch_json(settings['url'], settings.get('token', '')) if origin == 'live' else (
        json.loads(path.read_text(encoding='utf-8')))
    mapping = config.UNICLUBS_FIELD_MAPPING if source == 'uniclubs' else config.CITY_FIELD_MAPPING
    return _parse_payload(payload, mapping, source), payload


def _failed_report(source, origin, outcome, message):
    """Return a consistent zero-write result for a failed or rejected source."""
    return {'source': source, 'origin': origin, 'outcome': outcome, 'message': message,
            'n_series': 0, 'n_events': 0, 'rows_read': 0, 'skipped': [], 'past': 0}


def _try_candidates(connection, source, taxonomy, candidates, settings, warnings,
                    include_past, now, snapshot):
    """Try candidates in order, stopping on sanity rejection and sanitizing failures."""
    for origin, path in candidates:
        try:
            records, payload = _load_candidate(source, origin, path, settings, now)
            if origin in ('live', 'excel') and not records:
                raise ImportRejected('Empty live source; existing data retained.')
            report = save_records(connection, records, source, taxonomy, include_past, now,
                                  is_placeholder=origin == 'placeholder',
                                  reconcile=origin in ('live', 'excel'))
            if origin == 'live':
                _save_snapshot(snapshot, payload, warnings)
            read, skipped, past = report['rows_read'], len(report['skipped']), report['past']
            messages = warnings + [f'{read} records read; {skipped} invalid; {past} ended skipped.']
            messages.extend(report['skipped'][:config.MAX_REPORTED_ROW_ERRORS])
            report.update(origin=origin, outcome='ok', message=' '.join(messages))
            return report
        except ImportRejected as error:
            return _failed_report(source, origin, 'rejected', str(error))
        except (OSError, ValueError, KeyError, TypeError, sqlite3.Error, requests.RequestException):
            warnings.append(f'{origin.capitalize()} input unavailable or invalid.')
    return _failed_report(source, 'placeholder', 'failed', ' '.join(warnings))


def _save_snapshot(path, payload, warnings):
    """Replace the snapshot only after successful validation and database storage."""
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_suffix('.tmp')
        temporary.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
        temporary.replace(path)
    except OSError:
        warnings.append('Imported data saved; snapshot could not be updated.')


def import_source(connection, source, taxonomy, include_past=False, now=None,
                  sources_dir=config.SOURCES_DIR, snapshot_dir=config.SNAPSHOT_DIR,
                  private_file=config.PRIVATE_SOURCES_FILE):
    """Try live/Excel, snapshot and placeholder sources and log one sanitized run result."""
    if source not in config.SOURCES:
        raise ValueError('Unknown source.')
    warnings, settings, candidates = [], {}, []
    try:
        settings = read_private_sources(private_file).get(source, {})
        if not isinstance(settings, dict):
            raise ValueError('Invalid source configuration.')
    except (OSError, ValueError):
        settings = {}
        warnings.append('Source configuration could not be read.')
    real, snapshot = sources_dir / config.UNISPORT_REAL_FILE.name, snapshot_dir / f'{source}.json'
    if source == 'unisport' and real.exists():
        candidates.append(('excel', real))
    elif source != 'unisport' and settings.get('url'):
        candidates.append(('live', None))
    if source != 'unisport' and snapshot.exists():
        candidates.append(('snapshot', snapshot))
    candidates.append(('placeholder', sources_dir / config.PLACEHOLDER_NAMES[source]))
    report = _try_candidates(connection, source, taxonomy, candidates, settings, warnings,
                             include_past, now, snapshot)
    database.log_import(connection, source, report['origin'], report['n_series'],
                        report['n_events'], report['outcome'], report['message'], now)
    return report


def import_all(connection, taxonomy, include_past=False, now=None, **paths):
    """Import the three sources independently and return their run reports."""
    return [import_source(connection, source, taxonomy, include_past, now, **paths)
            for source in config.SOURCES]


